#include <cmath>
#include <algorithm>
extern "C" void render(const double* p,int n,float* img,int N,double scale){
 double rx=p[0],ry=p[1],th=atan2(p[4]-p[1],p[3]-p[0]); double w=0,d=0;
 for(int k=0;k<n;k++){
 double x=p[k*3],y=p[k*3+1],z=std::max(0.,std::min(15.,p[k*3+2]));
 double W=std::max(0.,1.187*z-.3),D=z>0?1.38+1.075*z:0,O=z>0?std::max(0.,11.15-.0967*(z-10.91)*(z-10.91)):0;
 w=.02*w+.98*W;d=.02*d+.98*D;
 double dx=x-rx,dy=y-ry,L=hypot(dx,dy);
 if(L>1.) th=atan2(dy,dx);
 if(L>0){double c=std::min(O,L)/L;rx=x-dx*c;ry=y-dy*c;}
 if(w<.001)continue;
 double ex=cos(th),ey=sin(th),nx=-ey,ny=ex,hw=w/2;
 double x0=std::min(rx+hw*nx,rx-hw*nx),x1=std::max(rx+hw*nx,rx-hw*nx);
 double y0=std::min(ry+hw*ny,ry-hw*ny),y1=std::max(ry+hw*ny,ry-hw*ny);
 x0=std::min(x0,x0-d*ex);x1=std::max(x1,x1-d*ex);y0=std::min(y0,y0-d*ey);y1=std::max(y1,y1-d*ey);
 int c0=std::max(0,int(floor(x0/scale))-1),c1=std::min(N-1,int(ceil(x1/scale))+1);
 int r0=std::max(0,int(floor(y0/scale))-1),r1=std::min(N-1,int(ceil(y1/scale))+1);
 for(int v=r0;v<=r1;v++)for(int u=c0;u<=c1;u++){
 double qx=(u+.5)*scale-rx,qy=(v+.5)*scale-ry;
 double s=-(qx*ex+qy*ey),t=qx*nx+qy*ny;
 double f=d*(1-4*t*t/(w*w))-s,g=sqrt(1+pow(8*d*t/(w*w),2));
 float a=std::max(0.,std::min(1.,std::min(s,f/g)/scale+.5));
 img[v*N+u]=std::max(img[v*N+u],a);
 }
 }
}
CPP

g++ -O3 -shared -fPIC /app/output/render.cpp -o /app/output/render.so

